sys_script_include.script:
var EquipmentRequestAjax = Class.create();
EquipmentRequestAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEquipmentInfo: function() {
        var equipmentId = this.getParameter('sysparm_equipment');
        var quantity = parseInt(this.getParameter('sysparm_quantity'), 10) || 1;

        var util = new EquipmentRequestUtil();
        var info = util.getEquipmentInfo(equipmentId);

        if (!info) {
            return JSON.stringify({ found: false });
        }

        var total = info.unit_cost * quantity;
        return JSON.stringify({
            found: true,
            name: info.name,
            active: info.active,
            unit_cost: info.unit_cost,
            stock_qty: info.stock_qty,
            enough_stock: info.stock_qty >= quantity,
            total_cost: total,
            approval_tier: util.getApprovalTier(total)
        });
    },

    type: 'EquipmentRequestAjax'
});
